"""Build a self-contained review from saved evidence; refresh after cofold completion.

Only the Python standard library is needed so the detached producer can run it.
"""
from artifacts import artifact, relative

from pathlib import Path
import csv,json,html,datetime,hashlib,collections
RUN=Path(__file__).resolve().parents[1]

def read(name):
    with artifact(name).open() as f:return list(csv.DictReader(f,delimiter='\t'))
def doc(name):return json.loads(artifact(name).read_text())
def esc(s):return html.escape(str(s))
def link(path,label=None):
    if path=='cofold/geometry_ranking.tsv' and not (RUN/path).exists():return esc(label or path)+' (pending)'
    path=relative(path) if not path.startswith(('https://','http://','cofold/','scripts/')) else path
    return f'<a href="{esc(path)}">{esc(label or path)}</a>'
def table(rows,cols):
    return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+esc(label)+'</th>' for key,label in cols)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+esc(r.get(key,''))+'</td>' for key,label in cols)+'</tr>' for r in rows)+'</tbody></table></div>'

def main():
    native=read('five_original_enzymes.tsv');counts=read('balanced_top5_reactions.tsv');top=read('top100_reactions.tsv');strict=read('strict_top5_reactions.tsv')
    mapping=doc('mapping_quality_summary.json');rebuilt=doc('direct_mapping_rebuild_summary.json');selection=doc('selection_audit.json');uncertainty=doc('paired_auroc_uncertainty.json')
    caveats=doc('native_reaction_caveats.json');manifest=doc('cofold/manifest.json');now=datetime.datetime.now(datetime.timezone.utc).isoformat()
    coordpath=RUN/'cofold/state/coordinator.json';coord=doc('cofold/state/coordinator.json') if coordpath.exists() else {}
    complete=list((RUN/'cofold/state').glob('*.done.json'));failures=[json.loads(p.read_text()) for p in (RUN/'cofold/state').glob('*.failure.json')]
    poses=list((RUN/'cofold/outputs').glob('*/by_seed/*/s42/*_model_*.pdb'))
    ready=sum(Path(x['msa']).exists() for x in manifest['inputs'])
    status=dict(generated_utc=now,coordinator_status=coord.get('status','not_launched'),completed_ensembles=len(complete),expected_ensembles=50,pdb_files_written=len(poses),expected_pdb_files=2500,msa_files_present=ready,failure_records=len(failures),terminal_failures=sum(x.get('attempts',0)>=2 for x in failures),workers=coord.get('workers',[]))
    (RUN/'cofold/status.json').write_text(json.dumps(status,indent=2))
    for r in counts:
        r['selected']='10';r['chemistry_score']=f"{float(r['chemistry_score']):.4f}"
    body=[]
    body.append('<h1>Amide synthetase discovery: response to Josh’s comments</h1><p class="date">Evidence snapshot: 17 October 2026. Report refreshed '+esc(now)+'.</p>')
    body.append('<div class="callout"><b>The supplied mapping was used, audited and preserved.</b> It is useful for discovery, but some links confuse reaction participants with reactions, and some identify noncatalytic subunits. The active pipeline now uses a separate, namespace-safe direct mapping. The balanced panel contains 50 distinct, full-length, sequence-verified proteins, ten from each of five qualifying reactions.</div>')
    body.append('<h2>1. The five original literature enzymes</h2><p>The Methods of the supplied Qian et al. PDF specify GenBank accessions, rather than UniProt accessions. Each GenBank sequence was fetched independently and compared residue-for-residue with its UniProt counterpart: all five match exactly across the full untagged sequence. Purification tags and codon optimization are not part of these reference sequences.</p>')
    body.append(table(native,[('enzyme','Enzyme'),('uniprot','Original UniProt'),('genbank','Paper’s GenBank'),('length','Residues'),('exact_sequence_match','Exact sequence match'),('native_reaction_modelseed_ids','Native reaction(s) in ModelSEED'),('native_nylon66_score','Nylon-6,6 target score')]))
    for r in native:
        body.append('<h3>'+esc(r['enzyme'])+'</h3><p><b>Original reaction:</b> '+esc(r['native_reaction'])+'</p><p><b>Resemblance to adipate + HMDA:</b> '+esc(r['similarity_reason'])+'</p><p><b>Paper’s nylon result:</b> '+esc(r['nylon_result'])+' '+link(r['source'],'Primary source')+'; '+link(r['uniprot_url'],'UniProt')+'; '+link(r['ncbi_url'],'GenBank')+'.</p>')
    body.append('<p>SfaB’s literature-tested 5-chlorovalerate/cadaverine benchmark scores <b>0.5717</b> in the same substrate heuristic. This is a promiscuous amidation reaction; its physiological role is acid adenylation. A blank native score means that no exact database molecular reaction can be scored, not zero biochemical similarity. Cyanophycin has unspecified repeat length; McbA’s native amidation and SfaB’s free-acid activation were not located as exact reactions in this snapshot.</p>')
    body.append('<details><summary>Important identity and database caveats</summary>'+''.join('<p><b>'+esc(k)+':</b> '+esc(v)+'</p>' for k,v in caveats.items())+'</details>')
    body.append('<p>The supplied PDF is the 4 September 2025 preprint. A '+link('https://doi.org/10.1039/D6GC00885B','2026 peer-reviewed version')+' is also available. Figures digitized from the supplied version are treated as approximate values. Its observed MA yield supports actual nylon-6,6 diad synthesis; it does not by itself establish enzymatic polymerization to high molecular weight.</p>')
    body.append('<h2>2. Reaction ranking and the five-reaction panel</h2><p>The existing structure-screened corpus contains <b>33,246 reactions</b>. Its reconstruction screen identifies 480 eligible amide-forming reactions; these 480 were rescored and ranked without a mapping-count cap. This is the scope of the top 100, not a claim that all symbolic or structurally unresolved ModelSEED reactions were rankable.</p><p>The main score examines the amide-forming partners: diacid/diamine or AB-monomer functionality, remaining free acid/amine ends, spacer lengths, aliphatic backbone and scaffold size. The weights are 0.35, 0.10, 0.20, 0.15 and 0.20. The historical heuristic gives the literal adipate/HMDA target <b>0.9650</b>, while favoring AB self-condensation slightly. This was an avoidable mismatch to the requested AA/BB target. The added nylon-6,6 score changes only the architecture term: AA/BB receives 1.0 credit and AB self-condensation 0.8. The exact target now scores <b>1.0000</b>; all other weights and the legacy score remain available. Neither score is molecular identity or a probability of activity. A score of 0.80 means 0.80 on the stated heuristic, not 80% chemical identity. The target-specific reweighting changes reaction order but leaves the five qualifying reaction groups and the 50 chosen sequences unchanged. Whole-reaction fingerprint cosine is retained separately for each query, because ATP turnover can dominate it.</p>')
    body.append('<p>The strict chemistry top five are shown separately. The earlier legacy top five had four reactions with no mapped IDs; the target-specific ranking also contains sparse or unmapped reactions. Both rankings are preserved. As authorized, the cofold panel uses the five highest-ranked ATP-dependent reactions with at least ten annotation-supported 95%-identity representatives after sequence and construct filters. No homologs from another reaction were relabeled to fill a group.</p>')
    body.append(table(strict,[('nylon66_rank','Target rank'),('rxn_id','ModelSEED'),('reaction_name','Reaction'),('nylon66_score','Target score'),('chemistry_score','Legacy score'),('mapped_accessions','Raw mapped IDs')]))
    body.append(table(counts,[('nylon66_rank','Target rank'),('rxn_id','Selected reaction'),('nylon66_score','Target score'),('chemistry_score','Legacy score'),('mapped_accessions','Raw IDs'),('exact_unique_sequences','Exact unique sequences, raw'),('supported_accessions','Supported full proteins'),('eligible_exact_sequences','Eligible exact sequences'),('clusters95','95% clusters'),('clusters50','50% clusters'),('selected','Cofold panel')]))
    reasons={
      'rxn00851':'D-Ala + D-Ala -> D-Ala-D-Ala. Makes the same carboxamide bond from bifunctional small monomers and preserves a terminal amine and acid. It is an AB self-condensation, closer to nylon-6 chemistry than the separate diacid/diamine architecture of nylon-6,6; alpha-amino-acid stereochemistry and short spacers are major differences.',
      'rxn02010':'MurE adds L-lysine to UDP-MurNAc-L-Ala-D-Glu. Lysine has two free amines, and the donor retains carboxyl functionality. It therefore offers relevant free-amine acylation, but recognizes a large nucleotide-sugar/peptide scaffold and a substituted, chiral amino acid instead of plain adipate/HMDA.',
      'rxn02011':'MurE adds meso-diaminopimelate to the same UDP-linked precursor. The acceptor is both a diamine and a diacid and has a relatively long aliphatic chain. Extra carboxyls, stereochemistry and the large UDP donor scaffold are substantial recognition differences. This is a different substrate-defined reaction group from lysine-adding MurE, not necessarily an independent enzyme fold.',
      'rxn00646':'Glutamate + cysteine -> gamma-glutamylcysteine. A free glutamate carboxyl couples to a free amine, leaving acid and amine functions in the product. Glutamate is a substituted C5 diacid, but cysteine is a thiol-bearing amino acid with one free amine, not a C6 diamine. The enzyme’s recognition and short spacer differ from the target.',
      'rxn00351':'Gamma-glutamylcysteine + glycine -> glutathione. ATP-dependent amide formation elongates a peptide and leaves an acid and a glutamyl amine. It supplies a mapped family with many supported sequences, but its peptide donor, thiol and very short glycine acceptor make it a weaker nylon-6,6 substrate analogue than the higher-scoring reactions.'}
    body.append(''.join('<p><b>'+esc(r)+':</b> '+esc(t)+'</p>' for r,t in reasons.items()))
    body.append('<p>Proteins were grouped by their original reaction links, collapsed by exact sequence, then clustered at <b>95% identity and 90% reciprocal coverage</b> to remove near duplicates even when they have different accessions or organism labels. Within each group, 50%-identity clusters were covered first, followed by farthest-point sampling on 3-mer sequence distance. The panel excludes annotated fragments, ambiguous residues, noncatalytic subunits and explicitly bifunctional proteins, to make one modeled catalytic site interpretable. Sequence identity was checked against the current UniProt record. The source mapping lacks genome/locus IDs, so shared-genome provenance is not inferred from protein names or taxonomy.</p>')
    body.append('<p>All 50 chosen sequences are distinct across the entire panel. Reaction-specific evidence is also included in the selected-protein table: four assignments have experimental evidence, five have curator-inference evidence, one is transferred from a homolog and forty use computational annotation. Direct reviewed annotations are not equivalent to experimental characterization; the computational assignments are explicitly labeled rather than represented as measured activities. The 95% clustering threshold is a practical redundancy definition; it does not prove that close homologs have identical substrate specificity. The independent global-alignment matrix below uses BLOSUM62, gap opening −10 and extension −0.5, with identity defined as exact matches divided by all global alignment columns.</p>')
    body.append('<p>'+link('selected50.tsv','Selected 50 and reaction membership')+' · '+link('selected50.fasta','Selected FASTA')+' · '+link('all_mapping_members_and_clusters.tsv','Every raw accession, sequence hash and cluster')+'</p><img src="figures/mapping_counts.png" alt="Raw and filtered mapping counts"><img src="figures/selected50_sequence_identity.png" alt="Pairwise identity of the 50 selected proteins">')
    body.append('<h2>3. How the mapping works and what is reliable</h2><p>The supplied headerless file is accession → comma-separated ModelSEED reaction IDs → protein sequence. Its documented construction joins reviewed UniProt catalytic Rhea cross-references to ModelSEED Rhea aliases, adds an indirect UniProt GO → Rhea → ModelSEED route, then merges the results. This is an annotation join, not a sequence-similarity search. The merged file does not retain which route, reaction evidence, release or individual reference generated each link. A correct reaction chemistry screen cannot repair an incorrect protein-to-reaction link.</p>')
    body.append('<p>The audit used that exact file (SHA-256 '+esc(mapping['mapping_sha256'])+'). It contains <b>262,380 accessions, 485,495 distinct links and 11,207 reactions</b>. All members of eight leading populated ATP-dependent groups were checked against current UniProt JSON records, plus a reproducible uniform random sample of 200 original links. The audit fetched 1,480 distinct proteins.</p>')
    body.append(table(read('mapping_quality_by_reaction.tsv'),[('reaction','Reaction'),('raw_accessions','Raw IDs'),('direct_rhea','Direct reaction match'),('component_collisions','Component-only collision'),('noncatalytic_subunits','Noncatalytic subunits'),('fragments','Fragments'),('supported_for_panel','Usable full proteins')]))
    body.append('<p><b>Observed failure:</b> 52 of 53 rxn02221 members are DJ-1/HchA-like deglycases with RHEA-COMP:14857 in their annotations; the actual indoleacetate–lysine reaction is RHEA:14857. Those numeric strings refer to different namespaces. Similarly, all 23 rxn01979 members have component-number collisions, and four rxn00646 members are regulatory rather than catalytic subunits. This establishes a reproducible failure pattern. The exact upstream script responsible cannot be proved from the final merged file alone because the intermediate source files are not present here.</p>')
    body.append('<p>In the uniform 200-link sample, 127 have direct reaction support, two have EC-only support, 34 show component-only matches and 37 remain unresolved. These are <b>annotation-concordance counts, not a measured catalytic accuracy</b>. An unresolved link is not automatically false. The sample should not be used to claim that every removed GO-derived link is wrong.</p>')
    body.append('<h3>New default mapping</h3><p>The replacement was rebuilt from <b>'+format(rebuilt['source_proteins'],',')+' reviewed, Rhea-annotated UniProt records from the saved source snapshot</b> and nonobsolete local ModelSEED aliases. Only exact <code>Rhea:RHEA:&lt;number&gt;</code> reaction identifiers generate links. RHEA-COMP, ChEBI and generic GO terms do not. Every emitted link retains its source Rhea ID, reaction- or direction-specific ECO/PubMed evidence, taxon, sequence hash and alias fan-out.</p>')
    body.append('<ul><li><b>Direct reviewed mapping:</b> '+format(rebuilt['mapped_pairs'],',')+' links, '+format(rebuilt['mapped_proteins'],',')+' proteins and '+format(rebuilt['mapped_reactions'],',')+' ModelSEED reactions.</li><li><b>Experimental evidence tier:</b> '+format(rebuilt['experimental_pairs'],',')+' links from '+format(rebuilt['experimental_proteins'],',')+' proteins. This requires ECO:0000269 on the corresponding reaction or physiological-direction field; it is evidence for that native annotation, not a nylon assay.</li><li><b>Comparison with supplied file:</b> '+format(rebuilt['old_pairs_retained'],',')+' old links retained; '+format(rebuilt['old_pairs_not_retained'],',')+' are not supported by this current direct-alias route; '+format(rebuilt['new_pairs_added_existing_accessions']+rebuilt['new_pairs_new_accessions'],',')+' new direct links added. Database changes and legitimate indirect links can also explain losses; removed does not universally mean incorrect.</li></ul>')
    body.append('<p>The project’s <code>mapping_policy.json</code> now selects the direct reviewed file and pins hashes of the mapping, evidence sidecar and experimental subset. The precomputed-link reader fails if an audited artifact is missing or changed, or a retained audited pair lacks valid evidence. The supplied mapping remains unchanged and can be explicitly selected for exploratory comparison. The dependent pipeline tables are refreshed with explicit provenance; earlier versions are archived under archive/pipeline_before_mapping_refresh_20261018 and ../mapping_robustness_20261019/before_correction. The separate 50-protein cofold cohort remains frozen.</p><p>The most reliable experimental shortlist should prioritize the experimental tier, then inspect the reaction-specific literature and verify the exact sequence/construct. Reviewed direct annotations inferred from homologs remain labeled as such. Reactions without a local Rhea alias remain genuine recall gaps; no unrelated protein is substituted.</p>')
    body.append('<p>'+link('uniprot-msd-direct-reviewed.tsv','New default mapping')+' · '+link('uniprot-msd-experimental-reviewed.tsv','Experimental tier')+' · '+link('direct_mapping_evidence.tsv.gz','Per-link provenance')+' · '+link('old_links_not_retained.tsv','Every old link not retained')+' · '+link('mapping_link_audit.tsv','Detailed focused and random-sample audit')+'</p>')
    robustness=RUN.parent/'mapping_robustness_20261019/after_audit.json'
    if robustness.exists():
        audit=json.loads(robustness.read_text())
        body.append('<h3>Mapping robustness rechecked 19 October 2026</h3><p>The independent reconstruction checks all '+format(audit['mapped_pairs'],',')+' mapping pairs against the saved source snapshot. The earlier parser borrowed reaction evidence for separately annotated physiological directions: 9,337 evidence rows were mis-scoped, including 8,175 tier assignments. The corrected parser leaves the mapping pairs and sequences unchanged and adds 40 pairs to the experimental subset. All recorded reconstruction checks now pass. A separate, nonrandom saved-JSON cross-check covers 2,683 links across 1,436 proteins, with no exact-ID or sequence mismatch. These are annotation-consistency checks, not a global catalytic-accuracy estimate.</p><p>Exact alias agreement also leaves chemical uncertainty: Rhea 11612–11615 map to two ModelSEED equations, one omitting water and protons. Both lie outside the current amide screen. Globally, 2,662 mapped reactions carry a raw status other than exactly OK; most involve incomplete/symbolic formula flags. These flags do not measure the false-assignment rate, and a full structural-equivalence audit was not performed. '+link('../../MAPPING_REVIEW.md','Current mapping review and remaining limitations')+' · '+link('../mapping_robustness_20261019/after_audit.json','Full consistency audit')+'.</p>')
    refreshed=artifact('pipeline_refresh_summary.json')
    if refreshed.exists():
        update=doc('pipeline_refresh_summary.json')
        counts_now=update['summaries'].get('precomputed_link',{})
        body.append('<h3>Pipeline integration refreshed '+esc(update['updated_utc'][:10])+'</h3><p>All '+str(update['refreshed_stages'])+' tracked dependency stages are current for their declared inputs. The precomputed route now retains all '+format(counts_now.get('candidate_rows',0),',')+' screened links and carries the reaction-specific evidence tier, Rhea identifiers, sequence hash and provenance through the master table and shortlist. The old default limit of 200 IDs per reaction is removed. Explicit caps select stronger evidence first. Family expansion uses verified reaction annotations as seeds; broad EC/name matches remain labeled hypotheses.</p><p>Freshness checks compare source, code and output hashes recursively. A changed upstream source invalidates its consumers even if an intermediate file has not yet changed; inputs changing during a stage prevent it being recorded as current. '+link('pipeline_refresh_summary.json','Refresh verification and counts')+' · '+link('../artifact_freshness.json','Full dependency registry')+'. These checks establish reproducibility and consistency, not biochemical validation.</p>')
    body.append('<h2>4. Does another statistic improve prediction of yield?</h2><p><b>Distance is worth reporting alongside angle, but no general yield predictor is validated here.</b> For each enzyme, all 50 poses contribute to the inverse-distance-weighted attack angle A = Σ(θ/d)/Σ(1/d). The accompanying harmonic distance is Dh = 50/Σ(1/d). We also tested smooth distance support and the fraction of poses satisfying joint distance/angle criteria. These distinguish a favorable angle at a remote substrate from an ensemble that consistently places the acid near the ATP phosphorus.</p>')
    body.append('<p>In the independent 49-enzyme in-house panel, models were fitted only on training enzymes, using fixed ridge strength and transforms. Leave-one-enzyme-out AUROC for the three strong producers increases from <b>0.659 to 0.703</b> when log harmonic distance is added to angle. The paired conditional bootstrap interval for the AUROC change is <b>'+f"{uncertainty['fixed_oof_prediction_bootstrap95'][0]:.3f} to {uncertainty['fixed_oof_prediction_bootstrap95'][1]:.3f}"+'</b>, spanning no improvement. Held-out continuous log-titre R² changes from <b>−0.046 to −0.050</b>; neither is useful as a quantitative titre predictor. Pose counts do not increase the experimental sample size.</p>')
    body.append('<img src="figures/yield_validation.png" alt="Held-out producer discrimination and titre prediction">')
    body.append('<p>For the supplied paper’s 12 digitized DdaG/SfaB mean yields (two enzymes × three acids × two diamines), adding distance improves leave-one-substrate-pair-out R² from <b>0.034 to 0.484</b> and log-yield RMSE from <b>0.539 to 0.394</b>. Leaving an entire acid out gives a much smaller R² of <b>0.045</b>. Leaving an entire enzyme out fails badly. These results support a within-enzyme substrate trend, not transfer to the five new enzyme groups. Adding step-2 amine geometry was also evaluated using the existing separate activated-intermediate ensembles; it did not consistently outperform angle plus distance across the held-out comparisons.</p>')
    body.append('<p>The earlier selected geometry score was tuned among 81 parameter settings on a 48-protein calibration panel. Its high calibration AUROC cannot be cited as independent validation. Here, model choices and failures are all saved, rather than reporting only the best fit. Percent yield and in-house µg/mL titre were analyzed separately. Digitized means were used once per experimental condition; reconstructed replicate dots were not treated as independent observations.</p>')
    body.append('<p>Useful next measurements are enzyme lifetime/remaining activity during the assay, soluble active-enzyme concentration and the amine-coupling step. Endpoint yield depends on these as well as acid activation. A distance/angle ensemble cannot by itself estimate them. The published 2026 paper discusses enzyme deactivation as a conversion limit; this is a rationale for measuring stability, not an already validated computational stability score.</p>')
    body.append('<p>'+link('panel_leave_one_enzyme_out_cv.tsv','49-enzyme validation')+' · '+link('literature_leave_one_substrate_pair_out_cv.tsv','Held-out substrate pairs')+' · '+link('literature_leave_one_enzyme_out_cv.tsv','Cross-enzyme transfer failures')+' · '+link('yield_analysis_audit.json','Methods and limitations')+'</p>')
    body.append('<h2>5. Cofolding status and interpretation</h2><div class="callout"><b>Current status: '+esc(status['coordinator_status'])+'</b><br>'+str(len(complete))+'/50 complete, structurally checked ensembles; '+str(len(poses))+'/2,500 PDB files written; '+str(ready)+'/50 MSA files present; '+str(status['terminal_failures'])+' exhausted inputs. A queued coordinator or a file count alone is not completed structural QC.</div>')
    body.append('<p>The frozen manifest contains one catalytic protein chain, ATP, two Mg²⁺ and explicitly dianionic adipate per input. This is the acid-activation comparison used previously; <b>HMDA and the activated intermediate are not in these 50 inputs</b>. Amine compatibility therefore remains a separate question. All five selected reaction groups use the ADP-forming acyl-phosphate route, so geometry is measured at ATP Pγ with O3B as the leaving oxygen. Two-metal occupancy is a family-based modeling hypothesis, not a per-homolog measurement.</p><p>Boltz-2 runs in exact mode with the exact-sequence MSA, 50 diffusion samples, three recycles, 200 sampling steps and seed 42. The installed stock sampler’s unusual <code>max_parallel_samples=41</code> yields ten batches of five, avoiding its known one-sample-cap defect. Four workers at most use exclusively reserved lambda13 GPUs with disjoint eight-CPU sets and capped native pools. The coordinator reserves no GPUs while waiting for MSAs.</p><p>Actual models are checked for the full protein sequence, all 50 output slots and confidence files, ATP atoms, adipate composition and two magnesium ions. This is standardized monomeric assembly QC, not proof that a complete biological oligomer or catalytic trajectory has been modeled. Failures have bounded retries; partial outputs are archived. Final output and geometry tables refresh this report automatically when the detached fleet exits.</p>')
    body.append('<p>'+link('cofold/manifest.json','Frozen cofold manifest')+' · '+link('cofold/status.json','Status snapshot')+' · '+link('cofold/evidence/node_preflight.json','Node dependency/resource preflight')+' · '+link('cofold/logs/coordinator.log','Coordinator log')+' · '+link('cofold/geometry_ranking.tsv','Completed geometry table, when available')+'</p>')
    body.append('<h2>6. Full ranked top 100</h2><p>Search by reaction ID, name or definition. All score components, substrate structures, query-specific fingerprint cosines and uncapped mapping counts are in '+link('top100_reactions.tsv','the top-100 TSV')+'. The full 480-reaction table is '+link('all_screened_reactions.tsv','also retained')+'.</p><input id="search" type="search" placeholder="Filter the ranked reactions" aria-label="Filter reactions">')
    body.append('<div id="ranking">'+table(top,[('nylon66_rank','Target rank'),('rxn_id','ModelSEED'),('reaction_name','Reaction'),('nylon66_score','Target score'),('chemistry_score','Legacy score'),('mapped_accessions','Raw mapping IDs'),('definition','Original reaction')])+'</div>')
    body.append('<h2>Reproducibility</h2><p>The evidence directory contains raw UniProt JSON for the focused audit, independent GenBank FASTAs, the complete reviewed-UniProt Rhea source snapshot, download release headers, source hashes, original and adapted fleet code, resource preflight, and archived preliminary selections. The original mapping was not edited. Regression checks cover the literal nylon target receiving full credit, the observed RHEA-COMP collision, reaction-specific evidence scope, policy hash enforcement, mapping ingestion and API behavior. The latest mapping regression log is saved with the 19 October robustness review.</p><p>Scripts: '+ ' · '.join(link('scripts/'+s,s) for s in ['audit_mapping.py','rebuild_direct_mapping.py','prepare_panel.py','native_enzymes.py','evaluate_yield.py','prepare_cofold.py','make_figures.py','annotate_selection.py','render_report.py'])+'.</p>')
    css='body{font:17px/1.6 system-ui,sans-serif;color:#182a36;background:#f6f8fa;max-width:1350px;margin:35px auto;padding:0 25px}h1{font-size:36px}h2{margin-top:48px;border-bottom:2px solid #b9cedc;padding-bottom:8px}h3{margin-bottom:4px}.date{color:#516574}.callout{background:#e8f2f8;border-left:5px solid #3279a2;padding:20px;margin:24px 0}.scroll{overflow:auto;background:white}table{border-collapse:collapse;width:100%;font-size:15px}th,td{padding:11px;border-bottom:1px solid #dbe3e8;text-align:left;vertical-align:top}th{background:#e9eff3;white-space:nowrap}tr:nth-child(even){background:#f5f8fa}a{color:#075c94}img{display:block;max-width:100%;height:auto;margin:24px auto}input{font:inherit;width:90%;padding:12px;margin:15px 0}code{background:#e8edf0;padding:2px 5px}details{background:#edf2f5;padding:15px}li{margin:9px 0}'
    js="document.querySelector('#search').addEventListener('input',e=>{let q=e.target.value.toLowerCase();document.querySelectorAll('#ranking tbody tr').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(q));});"
    page='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Amide synthetase discovery review</title><style>'+css+'</style><main>'+''.join(body)+'</main><script>'+js+'</script></html>'
    tmp=RUN/'report.html.tmp';tmp.write_text(page);tmp.replace(RUN/'report.html')
    print(json.dumps(status,indent=2))

if __name__=='__main__':main()
